// Auto-generated for the Unit Board — 搭配詞 連接詞 Connectives (tools/colloc_emit.py)
window.CC_DASHBOARD_UNITS = [{"unit":1,"theme":"however – rather","cards":[{"w":"The hotel was expensive; however, the service was disappointing.","p":"conj.","d":"however · contrast","c":"這家飯店很貴；然而，服務卻令人失望。","s":""},{"w":"However hard he tried, he could not open the jar.","p":"conj.","d":"however · contrast","c":"不管他多努力，都打不開那個罐子。","s":""},{"w":"She is talented. However, talent alone does not guarantee success.","p":"conj.","d":"however · contrast","c":"她很有才華。然而，光有才華並不保證成功。","s":""},{"w":"The plan was risky; nevertheless, they went ahead with it.","p":"conj.","d":"nevertheless · concession","c":"計畫有風險；儘管如此，他們仍進行。","s":""},{"w":"He was exhausted but nevertheless finished the marathon.","p":"conj.","d":"nevertheless · concession","c":"他筋疲力盡，但仍然跑完了馬拉松。","s":""},{"w":"The evidence is weak. Nevertheless, the police continue to investigate.","p":"conj.","d":"nevertheless · concession","c":"證據薄弱。儘管如此，警方仍持續調查。","s":""},{"w":"The film received poor reviews but was nonetheless a box-office hit.","p":"conj.","d":"nonetheless · concession","c":"這部電影評價不佳，但票房依然大賣。","s":""},{"w":"The task is difficult; nonetheless, we must complete it on time.","p":"conj.","d":"nonetheless · concession","c":"任務困難；儘管如此，我們必須準時完成。","s":""},{"w":"Some students learn best by listening, whereas others prefer reading.","p":"conj.","d":"whereas · contrast","c":"有些學生靠聽講學得最好，而其他人則偏好閱讀。","s":""},{"w":"My brother loves crowds, whereas I would rather stay home.","p":"conj.","d":"whereas · contrast","c":"我哥哥喜歡人群，而我寧願待在家。","s":""},{"w":"The north is dry and cold, whereas the south is humid.","p":"conj.","d":"whereas · contrast","c":"北部乾冷，而南部潮濕。","s":""},{"w":"While I understand your concern, I cannot change the rules.","p":"conj.","d":"while · contrast","c":"雖然我理解你的顧慮，但我無法更改規定。","s":""},{"w":"Some people enjoy spicy food, while others cannot stand it.","p":"conj.","d":"while · contrast","c":"有些人愛吃辣，而有些人完全受不了。","s":""},{"w":"While the idea sounds good, it would cost too much.","p":"conj.","d":"while · contrast","c":"這個想法聽起來不錯，但花費太高。","s":""},{"w":"Whilst the report is thorough, it ignores several key issues.","p":"conj.","d":"whilst · contrast","c":"這份報告雖詳盡，卻忽略了幾個關鍵問題。","s":""},{"w":"Last year sales fell sharply. By contrast, this year they have doubled.","p":"conj.","d":"by contrast · contrast","c":"去年銷售大跌。相比之下，今年翻了一倍。","s":""},{"w":"The city is noisy and crowded; the village, by contrast, is peaceful.","p":"conj.","d":"by contrast · contrast","c":"城市嘈雜擁擠；相比之下，村莊寧靜。","s":""},{"w":"In contrast to his brother, Tom is quiet and shy.","p":"conj.","d":"in contrast · contrast","c":"和他哥哥相反，湯姆安靜又害羞。","s":""},{"w":"The first test was easy. In contrast, the second was extremely hard.","p":"conj.","d":"in contrast · contrast","c":"第一次考試很簡單。相反地，第二次極難。","s":""},{"w":"He is not lazy at all; on the contrary, he works harder than anyone.","p":"conj.","d":"on the contrary · contrast","c":"他一點也不懶；相反地，他比任何人都努力。","s":""},{"w":"The medicine did not help. On the contrary, it made her feel worse.","p":"conj.","d":"on the contrary · contrast","c":"這藥沒有幫助。相反地，它讓她更不舒服。","s":""},{"w":"Living downtown is convenient; on the other hand, rent is very high.","p":"conj.","d":"on the other hand · contrast","c":"住市中心很方便；另一方面，房租非常高。","s":""},{"w":"The job pays well. On the other hand, the hours are terribly long.","p":"conj.","d":"on the other hand · contrast","c":"這工作薪水好。另一方面，工時長得可怕。","s":""},{"w":"Exercise improves mood; conversely, inactivity can lead to depression.","p":"conj.","d":"conversely · contrast","c":"運動改善情緒；反之，不活動可能導致憂鬱。","s":""},{"w":"Higher prices reduce demand. Conversely, lower prices usually increase it.","p":"conj.","d":"conversely · contrast","c":"價格上漲會降低需求。反之，降價通常會增加需求。","s":""},{"w":"We didn't go to the beach; instead, we stayed home and watched movies.","p":"conj.","d":"instead · contrast","c":"我們沒去海邊；反而待在家看電影。","s":""},{"w":"Instead of complaining, why don't you try to fix the problem?","p":"conj.","d":"instead · contrast","c":"與其抱怨，你為何不試著解決問題？","s":""},{"w":"The problem is not a lack of money but rather a lack of planning.","p":"conj.","d":"rather · contrast","c":"問題不在於缺錢，而在於缺乏規劃。","s":""},{"w":"I would rather walk than wait for the crowded bus.","p":"conj.","d":"rather · contrast","c":"我寧願走路，也不要等擠滿人的公車。","s":""},{"w":"Rather than argue, she quietly left the room.","p":"conj.","d":"rather · contrast","c":"她沒有爭辯，而是靜靜離開房間。","s":""}]},{"unit":2,"theme":"yet – notwithstanding","cards":[{"w":"The puzzle looks simple, yet few people can solve it.","p":"conj.","d":"yet · contrast","c":"這個謎題看似簡單，卻很少有人解得開。","s":""},{"w":"He has failed many times, yet he never gives up.","p":"conj.","d":"yet · contrast","c":"他失敗了很多次，但從不放棄。","s":""},{"w":"It is a strange yet beautiful piece of music.","p":"conj.","d":"yet · contrast","c":"這是一首奇特卻優美的樂曲。","s":""},{"w":"The weather was terrible. Still, thousands of fans attended the concert.","p":"conj.","d":"still · concession","c":"天氣很糟。儘管如此，仍有數千名粉絲參加演唱會。","s":""},{"w":"I know it is expensive, but I still want to buy it.","p":"conj.","d":"still · concession","c":"我知道它很貴，但我還是想買。","s":""},{"w":"The road was icy. Even so, he insisted on driving home.","p":"conj.","d":"even so · concession","c":"路面結冰。即便如此，他仍堅持開車回家。","s":""},{"w":"The test was hard, but even so, most students passed.","p":"conj.","d":"even so · concession","c":"考試很難，但即便如此，大多數學生還是及格了。","s":""},{"w":"It may be a small gift, but I appreciate it all the same.","p":"conj.","d":"all the same · concession","c":"這或許是個小禮物，但我還是很感謝。","s":""},{"w":"The chances are slim. All the same, we should try.","p":"conj.","d":"all the same · concession","c":"機會渺茫。儘管如此，我們仍應該嘗試。","s":""},{"w":"Although it was raining heavily, the game continued as planned.","p":"conj.","d":"although · concession","c":"雖然下著大雨，比賽仍照計畫進行。","s":""},{"w":"She accepted the offer, although the salary was lower than expected.","p":"conj.","d":"although · concession","c":"她接受了這份工作，儘管薪水比預期低。","s":""},{"w":"Though he is only ten, he plays the piano like a professional.","p":"conj.","d":"though · concession","c":"雖然他才十歲，鋼琴卻彈得像專業人士。","s":""},{"w":"The restaurant is small. The food is excellent, though.","p":"conj.","d":"though · concession","c":"這家餐廳很小。不過，食物很棒。","s":""},{"w":"Strange though it may seem, the plan actually worked.","p":"conj.","d":"though · concession","c":"雖然看似奇怪，這計畫確實奏效了。","s":""},{"w":"Even though she studied all night, she failed the exam.","p":"conj.","d":"even though · concession","c":"儘管她熬夜讀了一整晚，考試還是不及格。","s":""},{"w":"He went to work even though he had a high fever.","p":"conj.","d":"even though · concession","c":"儘管發高燒，他還是去上班了。","s":""},{"w":"Despite the heavy traffic, we arrived at the airport on time.","p":"conj.","d":"despite · concession","c":"儘管交通繁忙，我們還是準時抵達機場。","s":""},{"w":"Despite being warned twice, he kept using his phone in class.","p":"conj.","d":"despite · concession","c":"儘管被警告兩次，他仍在課堂上用手機。","s":""},{"w":"Despite the fact that he is rich, he lives very simply.","p":"conj.","d":"despite · concession","c":"儘管他很有錢，卻過得非常簡樸。","s":""},{"w":"In spite of her injury, she finished the race in second place.","p":"conj.","d":"in spite of · concession","c":"儘管受傷，她仍以第二名完賽。","s":""},{"w":"They enjoyed the picnic in spite of the cold wind.","p":"conj.","d":"in spite of · concession","c":"儘管寒風刺骨，他們仍享受了野餐。","s":""},{"w":"Everyone is welcome to join, regardless of age or experience.","p":"conj.","d":"regardless of · concession","c":"無論年齡或經驗，歡迎所有人參加。","s":""},{"w":"The company treats all customers equally, regardless of how much they spend.","p":"conj.","d":"regardless of · concession","c":"這家公司對所有顧客一視同仁，不論消費多少。","s":""},{"w":"He decided to go ahead regardless of the risks involved.","p":"conj.","d":"regardless of · concession","c":"他決定不顧相關風險繼續進行。","s":""},{"w":"The forecast predicted rain, but we went hiking regardless.","p":"conj.","d":"regardless · concession","c":"天氣預報說會下雨，但我們還是照樣去爬山。","s":""},{"w":"Her parents objected, but she married him regardless.","p":"conj.","d":"regardless · concession","c":"她父母反對，但她還是嫁給了他。","s":""},{"w":"Notwithstanding the bad weather, the ceremony was held outdoors.","p":"conj.","d":"notwithstanding · concession","c":"儘管天氣惡劣，典禮仍在戶外舉行。","s":""},{"w":"The project went ahead, notwithstanding the objections of local residents.","p":"conj.","d":"notwithstanding · concession","c":"儘管當地居民反對，計畫仍繼續進行。","s":""}]},{"unit":3,"theme":"albeit – therefore","cards":[{"w":"The company made a profit, albeit a small one.","p":"conj.","d":"albeit · concession","c":"這家公司獲利了，儘管金額不大。","s":""},{"w":"He agreed to help, albeit reluctantly.","p":"conj.","d":"albeit · concession","c":"他答應幫忙，儘管不太情願。","s":""},{"w":"Granted, the plan has flaws, but it is still our best option.","p":"conj.","d":"granted · concession","c":"的確，這個計畫有缺點，但它仍是最佳選項。","s":""},{"w":"Granted that the price is high, the quality is worth it.","p":"conj.","d":"granted · concession","c":"儘管價格高，品質是值得的。","s":""},{"w":"Admittedly, I made a mistake, but it was not entirely my fault.","p":"conj.","d":"admittedly · concession","c":"誠然，我犯了錯，但這不完全是我的錯。","s":""},{"w":"The results are, admittedly, far from perfect.","p":"conj.","d":"admittedly · concession","c":"這些結果誠然遠非完美。","s":""},{"w":"True, the car is old, but it still runs perfectly well.","p":"conj.","d":"true · concession","c":"沒錯，這車很舊，但它仍跑得好好的。","s":""},{"w":"It is true that he is strict, but his students respect him.","p":"conj.","d":"true · concession","c":"他確實嚴格，但學生們尊敬他。","s":""},{"w":"The food was bad, but at least the service was friendly.","p":"conj.","d":"at least · concession","c":"食物很差，但至少服務很親切。","s":""},{"w":"It will take at least three hours to finish the report.","p":"conj.","d":"at least · concession","c":"完成這份報告至少要三小時。","s":""},{"w":"The movie is too long. That said, the acting is superb.","p":"conj.","d":"that said · concession","c":"這部電影太長了。話雖如此，演技一流。","s":""},{"w":"I rarely eat dessert. That said, I can never refuse chocolate cake.","p":"conj.","d":"that said · concession","c":"我很少吃甜點。話雖如此，我從不拒絕巧克力蛋糕。","s":""},{"w":"The hotel is far from downtown. Having said that, the view is amazing.","p":"conj.","d":"having said that · concession","c":"這家飯店離市中心很遠。話雖如此，景色很迷人。","s":""},{"w":"The tickets were sold out, but we went to the stadium anyway.","p":"conj.","d":"anyway · concession","c":"門票賣完了，但我們還是去了體育場。","s":""},{"w":"I don't need a new phone. Anyway, I can't afford one.","p":"conj.","d":"anyway · concession","c":"我不需要新手機。反正，我也買不起。","s":""},{"w":"It was too late to apologize, but he called her anyhow.","p":"conj.","d":"anyhow · concession","c":"道歉已經太遲了，但他還是打了電話給她。","s":""},{"w":"Anyhow, let's get back to the main point of the meeting.","p":"conj.","d":"anyhow · concession","c":"總之，我們回到會議的重點吧。","s":""},{"w":"Don't be too hard on him; after all, he is only a child.","p":"conj.","d":"after all · concession","c":"別對他太嚴厲；畢竟，他只是個孩子。","s":""},{"w":"The exam was not so difficult after all.","p":"conj.","d":"after all · concession","c":"這次考試終究沒那麼難。","s":""},{"w":"She decided to come to the party after all.","p":"conj.","d":"after all · concession","c":"她最後還是決定來參加派對。","s":""},{"w":"It was a long trip; at any rate, we arrived safely.","p":"conj.","d":"at any rate · concession","c":"這是一段漫長的旅程；無論如何，我們安全抵達了。","s":""},{"w":"At any rate, the decision has already been made.","p":"conj.","d":"at any rate · concession","c":"無論如何，決定已經做出來了。","s":""},{"w":"The store may be closed, but in any case we can order online.","p":"conj.","d":"in any case · concession","c":"商店可能關了，但無論如何我們可以網購。","s":""},{"w":"In any case, I will call you as soon as I arrive.","p":"conj.","d":"in any case · concession","c":"無論如何，我一到就會打給你。","s":""},{"w":"The team lost; the fans nevertheless cheered loudly for them.","p":"conj.","d":"nevertheless · contrast","c":"球隊輸了；儘管如此，粉絲仍大聲為他們加油。","s":""},{"w":"He did not study for the test; therefore, he failed.","p":"conj.","d":"therefore · cause/result","c":"他沒有為考試讀書；因此，他不及格。","s":""},{"w":"The road is closed for repairs. Therefore, traffic is being diverted.","p":"conj.","d":"therefore · cause/result","c":"道路封閉維修。因此，車流正在改道。","s":""},{"w":"Prices rose sharply and demand therefore dropped.","p":"conj.","d":"therefore · cause/result","c":"價格大漲，需求因此下降。","s":""}]},{"unit":4,"theme":"thus – to this end","cards":[{"w":"The factory closed, thus leaving hundreds of workers unemployed.","p":"conj.","d":"thus · cause/result","c":"工廠關閉，使數百名工人失業。","s":""},{"w":"Fewer trees are being cut; thus, the forest is slowly recovering.","p":"conj.","d":"thus · cause/result","c":"砍伐的樹木減少；因此，森林正慢慢恢復。","s":""},{"w":"The team trained harder and thus improved their results.","p":"conj.","d":"thus · cause/result","c":"這支隊伍更努力訓練，因而成績提升。","s":""},{"w":"The town has little industry; hence, many young people move away.","p":"conj.","d":"hence · cause/result","c":"這座城鎮工業少；因此，許多年輕人搬離。","s":""},{"w":"He lost his passport, hence the delay in his departure.","p":"conj.","d":"hence · cause/result","c":"他丟了護照，所以才延後出發。","s":""},{"w":"Hence the need for stricter safety rules.","p":"conj.","d":"hence · cause/result","c":"因此需要更嚴格的安全規範。","s":""},{"w":"It rained for a week; consequently, the river flooded the village.","p":"conj.","d":"consequently · cause/result","c":"下了一週的雨；結果，河水淹沒了村莊。","s":""},{"w":"She missed the deadline and consequently lost the contract.","p":"conj.","d":"consequently · cause/result","c":"她錯過了期限，結果失去了合約。","s":""},{"w":"The bridge collapsed, and as a result, the highway was closed for months.","p":"conj.","d":"as a result · cause/result","c":"橋塌了，結果公路關閉了好幾個月。","s":""},{"w":"As a result of the storm, thousands of homes lost power.","p":"conj.","d":"as a result · cause/result","c":"由於暴風雨，數千戶住家停電。","s":""},{"w":"He ignored the warnings and, as a consequence, lost all his savings.","p":"conj.","d":"as a consequence · cause/result","c":"他忽視警告，結果失去了所有積蓄。","s":""},{"w":"As a consequence of the strike, no trains ran today.","p":"conj.","d":"as a consequence · cause/result","c":"由於罷工，今天沒有火車行駛。","s":""},{"w":"The rules have changed; please adjust your plans accordingly.","p":"conj.","d":"accordingly · cause/result","c":"規定已改變；請據此調整你的計畫。","s":""},{"w":"He was told the meeting was urgent and acted accordingly.","p":"conj.","d":"accordingly · cause/result","c":"他被告知會議緊急，便據此行動。","s":""},{"w":"She resigned, thereby ending twenty years of service.","p":"conj.","d":"thereby · cause/result","c":"她辭職，從而結束了二十年的服務。","s":""},{"w":"The new law raises taxes, thereby reducing the deficit.","p":"conj.","d":"thereby · cause/result","c":"新法提高稅收，從而減少赤字。","s":""},{"w":"He skipped breakfast, thereby saving ten minutes.","p":"conj.","d":"thereby · cause/result","c":"他沒吃早餐，藉此省下十分鐘。","s":""},{"w":"It was getting dark, so we decided to head home.","p":"conj.","d":"so · cause/result","c":"天漸漸黑了，所以我們決定回家。","s":""},{"w":"The store was closed, so I couldn't buy milk.","p":"conj.","d":"so · cause/result","c":"商店關了，所以我買不到牛奶。","s":""},{"w":"Speak louder so that everyone in the back can hear you.","p":"conj.","d":"so that · purpose","c":"說大聲一點，好讓後面的人都聽得到。","s":""},{"w":"He saved money for years so that he could buy a house.","p":"conj.","d":"so that · purpose","c":"他存了多年的錢，為的是能買房子。","s":""},{"w":"The teacher repeated the rule in order that no one would misunderstand.","p":"conj.","d":"in order that · purpose","c":"老師重複了規則，以免有人誤解。","s":""},{"w":"We left early in order that we might avoid the traffic.","p":"conj.","d":"in order that · purpose","c":"我們提早出發，以便避開車潮。","s":""},{"w":"In order to pass the exam, you must practice every day.","p":"conj.","d":"in order to · purpose","c":"為了通過考試，你必須每天練習。","s":""},{"w":"She moved to Taipei in order to find a better job.","p":"conj.","d":"in order to · purpose","c":"她搬到台北是為了找更好的工作。","s":""},{"w":"Read the instructions carefully so as to avoid mistakes.","p":"conj.","d":"so as to · purpose","c":"仔細閱讀說明，以避免錯誤。","s":""},{"w":"We aim to reduce waste. To this end, plastic bags are now banned.","p":"conj.","d":"to this end · purpose","c":"我們致力於減少垃圾。為此，塑膠袋現已禁用。","s":""},{"w":"The city wants cleaner air; to this end, it is adding bike lanes.","p":"conj.","d":"to this end · purpose","c":"這座城市想要更乾淨的空氣；為此，正在增設自行車道。","s":""}]},{"unit":5,"theme":"with a view to – due to","cards":[{"w":"The company hired more staff with a view to expanding overseas.","p":"conj.","d":"with a view to · purpose","c":"這家公司增聘員工，以期拓展海外業務。","s":""},{"w":"He wrote the number down lest he should forget it.","p":"conj.","d":"lest · purpose","c":"他把號碼寫下來，以免忘記。","s":""},{"w":"Speak softly lest the baby wake up.","p":"conj.","d":"lest · purpose","c":"小聲說話，以免嬰兒醒來。","s":""},{"w":"She hid the letter lest her parents find it.","p":"conj.","d":"lest · purpose","c":"她把信藏起來，以免父母發現。","s":""},{"w":"He didn't tell the truth for fear that he would be punished.","p":"conj.","d":"for fear that · purpose","c":"他沒說實話，因為怕被處罰。","s":""},{"w":"The flight was canceled because of the heavy fog.","p":"conj.","d":"because · cause/result","c":"由於大霧，航班取消了。","s":""},{"w":"Just because it is cheap doesn't mean it is bad.","p":"conj.","d":"because · cause/result","c":"便宜不代表就不好。","s":""},{"w":"Since you are already here, you might as well stay for dinner.","p":"conj.","d":"since · cause/result","c":"既然你已經來了，不如留下來吃晚餐。","s":""},{"w":"Since the shop was closed, we went to another one.","p":"conj.","d":"since · cause/result","c":"由於那家店關了，我們去了另一家。","s":""},{"w":"As it was late, we decided to take a taxi home.","p":"conj.","d":"as · cause/result","c":"由於時間晚了，我們決定搭計程車回家。","s":""},{"w":"As the population grows, the demand for housing increases.","p":"conj.","d":"as · cause/result","c":"隨著人口成長，住房需求增加。","s":""},{"w":"He must be tired, for he has been working since dawn.","p":"conj.","d":"for · cause/result","c":"他一定很累，因為他從天亮就開始工作。","s":""},{"w":"Now that the exams are over, we can finally relax.","p":"conj.","d":"now that · cause/result","c":"既然考試結束了，我們終於可以放鬆了。","s":""},{"w":"Now that you mention it, I do remember seeing him there.","p":"conj.","d":"now that · cause/result","c":"既然你提到了，我確實記得在那裡見過他。","s":""},{"w":"Seeing that nobody objected, the chairman closed the meeting.","p":"conj.","d":"seeing that · cause/result","c":"既然沒人反對，主席就結束了會議。","s":""},{"w":"The two plans differ in that one costs far more.","p":"conj.","d":"in that · cause/result","c":"這兩個計畫的不同在於其中一個貴得多。","s":""},{"w":"The test is unfair in that it favors native speakers.","p":"conj.","d":"in that · cause/result","c":"這項測驗不公平，因為它偏向母語人士。","s":""},{"w":"He is lucky in that he has supportive parents.","p":"conj.","d":"in that · cause/result","c":"他很幸運，因為他有支持他的父母。","s":""},{"w":"Given that she is new, her performance has been impressive.","p":"conj.","d":"given that · cause/result","c":"考量到她是新人，她的表現令人印象深刻。","s":""},{"w":"Given that it is raining, the match will probably be postponed.","p":"conj.","d":"given that · cause/result","c":"鑑於正在下雨，比賽可能會延後。","s":""},{"w":"Given the circumstances, the team did remarkably well.","p":"conj.","d":"given · cause/result","c":"考量到當時情況，這支隊伍表現非常好。","s":""},{"w":"Given his age, his memory is surprisingly sharp.","p":"conj.","d":"given · cause/result","c":"以他的年紀來說，他的記憶力驚人地好。","s":""},{"w":"Considering the traffic, we had better leave an hour early.","p":"conj.","d":"considering · cause/result","c":"考慮到交通，我們最好提早一小時出發。","s":""},{"w":"She did well, considering that it was her first attempt.","p":"conj.","d":"considering · cause/result","c":"考慮到這是她第一次嘗試，她表現得不錯。","s":""},{"w":"Owing to a technical problem, the website is temporarily unavailable.","p":"conj.","d":"owing to · cause/result","c":"由於技術問題，網站暫時無法使用。","s":""},{"w":"The match was delayed owing to heavy rain.","p":"conj.","d":"owing to · cause/result","c":"由於大雨，比賽延後。","s":""},{"w":"The delay was due to an accident on the highway.","p":"conj.","d":"due to · cause/result","c":"延誤是由於高速公路上的一場事故。","s":""},{"w":"Due to rising costs, the museum has raised its ticket prices.","p":"conj.","d":"due to · cause/result","c":"由於成本上升，博物館提高了票價。","s":""}]},{"unit":6,"theme":"on account of – not to mention","cards":[{"w":"The school was closed on account of the typhoon.","p":"conj.","d":"on account of · cause/result","c":"由於颱風，學校停課了。","s":""},{"w":"He retired early on account of poor health.","p":"conj.","d":"on account of · cause/result","c":"他因健康不佳而提早退休。","s":""},{"w":"Thanks to your help, we finished the project ahead of schedule.","p":"conj.","d":"thanks to · cause/result","c":"多虧你的幫忙，我們提前完成了專案。","s":""},{"w":"Thanks to the new bridge, the trip now takes only ten minutes.","p":"conj.","d":"thanks to · cause/result","c":"多虧了新橋，現在車程只要十分鐘。","s":""},{"w":"In view of the recent complaints, the policy will be reviewed.","p":"conj.","d":"in view of · cause/result","c":"鑑於近期的投訴，這項政策將被重新檢討。","s":""},{"w":"In light of new evidence, the case has been reopened.","p":"conj.","d":"in light of · cause/result","c":"鑑於新證據，此案已重新展開調查。","s":""},{"w":"The bridge is unsafe. For this reason, it will be closed to traffic.","p":"conj.","d":"for this reason · cause/result","c":"這座橋不安全。因此，它將禁止通行。","s":""},{"w":"He practiced every day. That is why he won the competition.","p":"conj.","d":"that is why · cause/result","c":"他每天練習。這就是他贏得比賽的原因。","s":""},{"w":"Higher wages raise costs, which in turn push up prices.","p":"conj.","d":"in turn · cause/result","c":"工資上漲提高成本，進而推高物價。","s":""},{"w":"She helped me, and I, in turn, helped her brother.","p":"conj.","d":"in turn · cause/result","c":"她幫了我，而我也轉而幫了她弟弟。","s":""},{"w":"Each student in turn read a paragraph aloud.","p":"conj.","d":"in turn · cause/result","c":"每位學生輪流朗讀一段。","s":""},{"w":"The house is too small; moreover, it is far from the station.","p":"conj.","d":"moreover · addition","c":"這房子太小了；此外，它離車站很遠。","s":""},{"w":"The job is well paid. Moreover, it offers excellent training.","p":"conj.","d":"moreover · addition","c":"這份工作薪水好。此外，它還提供優良的訓練。","s":""},{"w":"The plan is too costly. Furthermore, it would take years to complete.","p":"conj.","d":"furthermore · addition","c":"這個計畫太昂貵。此外，它需要好幾年才能完成。","s":""},{"w":"Smoking harms your lungs; furthermore, it affects those around you.","p":"conj.","d":"furthermore · addition","c":"吸菸傷害你的肺；此外，也影響周遭的人。","s":""},{"w":"In addition to English, she speaks French and Japanese fluently.","p":"conj.","d":"in addition · addition","c":"除了英語，她還能流利地說法語和日語。","s":""},{"w":"The hotel offers free breakfast. In addition, guests may use the pool.","p":"conj.","d":"in addition · addition","c":"這家飯店提供免費早餐。此外，房客可使用泳池。","s":""},{"w":"The course covers grammar. Additionally, students practice speaking every week.","p":"conj.","d":"additionally · addition","c":"這門課涵蓋文法。此外，學生每週練習口說。","s":""},{"w":"I don't want to go out; besides, it's raining.","p":"conj.","d":"besides · addition","c":"我不想出門；再說，正在下雨。","s":""},{"w":"Besides being a great teacher, she is also a talented writer.","p":"conj.","d":"besides · addition","c":"除了是位好老師，她還是個有才華的作家。","s":""},{"w":"Who else was at the party besides Tom?","p":"conj.","d":"besides · addition","c":"除了湯姆，派對上還有誰？","s":""},{"w":"The restaurant serves great food and also has a lovely view.","p":"conj.","d":"also · addition","c":"這家餐廳食物很棒，也有美麗的景觀。","s":""},{"w":"The school teaches art as well as science and math.","p":"conj.","d":"as well as · addition","c":"這所學校除了教理科和數學，也教藝術。","s":""},{"w":"She is a doctor as well as a mother of three.","p":"conj.","d":"as well as · addition","c":"她既是醫生，也是三個孩子的媽媽。","s":""},{"w":"Not only did he win the race, but he also broke the record.","p":"conj.","d":"not only … but also · addition","c":"他不僅贏了比賽，還打破了紀錄。","s":""},{"w":"The book is not only informative but also entertaining.","p":"conj.","d":"not only … but also · addition","c":"這本書不僅資訊豐富，也很有趣。","s":""},{"w":"The trip was tiring, not to mention expensive.","p":"conj.","d":"not to mention · addition","c":"這趟旅行很累人，更別說花費高昂了。","s":""},{"w":"He speaks three languages, not to mention his skill in music.","p":"conj.","d":"not to mention · addition","c":"他會說三種語言，更別提他的音樂才能。","s":""}]},{"unit":7,"theme":"let alone – obviously","cards":[{"w":"He can barely walk, let alone run a marathon.","p":"conj.","d":"let alone · addition","c":"他幾乎無法走路，更別說跑馬拉松了。","s":""},{"w":"I can't afford a bike, let alone a car.","p":"conj.","d":"let alone · addition","c":"我連自行車都買不起，更別說汽車了。","s":""},{"w":"She wouldn't speak to him, much less forgive him.","p":"conj.","d":"much less · addition","c":"她連跟他說話都不肯，更別說原諒他了。","s":""},{"w":"I have never seen snow, much less skied on it.","p":"conj.","d":"much less · addition","c":"我從沒見過雪，更別說滑雪了。","s":""},{"w":"He never reads newspapers, still less academic journals.","p":"conj.","d":"still less · addition","c":"他從不讀報紙，更別說學術期刊了。","s":""},{"w":"The hotel was cheap and clean; what is more, it was near the beach.","p":"conj.","d":"what is more · addition","c":"這家飯店便宜又乾淨；更棒的是，它靠近海灘。","s":""},{"w":"I lost my wallet, and on top of that, I missed the last train.","p":"conj.","d":"on top of that · addition","c":"我丟了錢包，更糟的是，還錯過了最後一班火車。","s":""},{"w":"Be honest, be kind, and above all, be yourself.","p":"conj.","d":"above all · emphasis","c":"要誠實，要善良，最重要的是，做你自己。","s":""},{"w":"Above all, remember to stay calm during the exam.","p":"conj.","d":"above all · emphasis","c":"最重要的是，記得在考試時保持冷靜。","s":""},{"w":"The results were disappointing; indeed, they were the worst in years.","p":"conj.","d":"indeed · emphasis","c":"結果令人失望；事實上，是多年來最差的。","s":""},{"w":"It is indeed a great honor to be here tonight.","p":"conj.","d":"indeed · emphasis","c":"今晚能在這裡確實是極大的榮幸。","s":""},{"w":"He is not a stranger; in fact, he is my cousin.","p":"conj.","d":"in fact · emphasis","c":"他不是陌生人；事實上，他是我表哥。","s":""},{"w":"The test was easy. In fact, I finished it in twenty minutes.","p":"conj.","d":"in fact · emphasis","c":"考試很簡單。事實上，我二十分鐘就寫完了。","s":""},{"w":"I thought the movie would be boring, but it was actually quite good.","p":"conj.","d":"actually · emphasis","c":"我以為電影會很無聊，但其實相當好看。","s":""},{"w":"Actually, I have never been to Japan.","p":"conj.","d":"actually · emphasis","c":"其實，我從沒去過日本。","s":""},{"w":"The students enjoyed the trip, the museum visit in particular.","p":"conj.","d":"in particular · emphasis","c":"學生們很享受這次旅行，尤其是參觀博物館。","s":""},{"w":"Nothing in particular happened at the meeting.","p":"conj.","d":"in particular · emphasis","c":"會議上沒發生什麼特別的事。","s":""},{"w":"Traffic is heavy in Taipei, particularly during rush hour.","p":"conj.","d":"particularly · emphasis","c":"台北交通繁忙，尤其是尖峰時段。","s":""},{"w":"I love fruit, especially mangoes in summer.","p":"conj.","d":"especially · emphasis","c":"我愛吃水果，尤其是夏天的芒果。","s":""},{"w":"Several countries, notably Japan, have aging populations.","p":"conj.","d":"notably · emphasis","c":"好幾個國家，特別是日本，面臨人口老化。","s":""},{"w":"The new rule means, in effect, that no one can leave early.","p":"conj.","d":"in effect · emphasis","c":"這條新規定實際上意味著沒人能提早離開。","s":""},{"w":"The company has, in effect, stopped hiring.","p":"conj.","d":"in effect · emphasis","c":"這家公司實際上已經停止招聘。","s":""},{"w":"In essence, the two proposals are the same.","p":"conj.","d":"in essence · emphasis","c":"本質上，這兩項提案是相同的。","s":""},{"w":"The two models are essentially identical except for the color.","p":"conj.","d":"essentially · emphasis","c":"這兩款除了顏色之外基本上一模一樣。","s":""},{"w":"The new policy will certainly affect small businesses.","p":"conj.","d":"certainly · emphasis","c":"新政策無疑會影響小型企業。","s":""},{"w":"She is undoubtedly the most gifted student in the class.","p":"conj.","d":"undoubtedly · emphasis","c":"她無疑是班上最有天賦的學生。","s":""},{"w":"Undoubtedly, the Internet has changed the way we learn.","p":"conj.","d":"undoubtedly · emphasis","c":"毫無疑問，網路改變了我們學習的方式。","s":""},{"w":"Obviously, we cannot finish the project without more funding.","p":"conj.","d":"obviously · emphasis","c":"顯然，沒有更多資金我們無法完成這項專案。","s":""}]},{"unit":8,"theme":"clearly – then","cards":[{"w":"Clearly, the current system is not working.","p":"conj.","d":"clearly · emphasis","c":"顯然，目前的制度行不通。","s":""},{"w":"Evidently, no one had told him about the change of plans.","p":"conj.","d":"evidently · emphasis","c":"顯然，沒有人告訴他計畫改變了。","s":""},{"w":"Of course, not everyone agrees with this view.","p":"conj.","d":"of course · emphasis","c":"當然，並非每個人都同意這個看法。","s":""},{"w":"Needless to say, the party was a great success.","p":"conj.","d":"needless to say · emphasis","c":"不用說，派對非常成功。","s":""},{"w":"His behavior at the dinner was rude, to say the least.","p":"conj.","d":"to say the least · emphasis","c":"他在晚餐時的行為至少可以說是無禮。","s":""},{"w":"Many animals, for example bears, sleep through the winter.","p":"conj.","d":"for example · example","c":"許多動物，例如熊，整個冬天都在睡覺。","s":""},{"w":"You should eat healthier food, for example fresh vegetables and fruit.","p":"conj.","d":"for example · example","c":"你應該吃更健康的食物，例如新鮮蔬果。","s":""},{"w":"Some jobs, for instance nursing, require long and irregular hours.","p":"conj.","d":"for instance · example","c":"有些工作，例如護理，需要長時間且不規律的工時。","s":""},{"w":"Taiwan is famous for its night-market snacks, such as stinky tofu.","p":"conj.","d":"such as · example","c":"台灣以夜市小吃聞名，例如臭豆腐。","s":""},{"w":"Two students were absent, namely Jack and Lily.","p":"conj.","d":"namely · example","c":"有兩位學生缺席，即傑克和莉莉。","s":""},{"w":"The project has one major problem, namely a lack of funding.","p":"conj.","d":"namely · example","c":"這個專案有一個大問題，即缺乏資金。","s":""},{"w":"Only one person can decide, namely the president.","p":"conj.","d":"namely · example","c":"只有一個人能決定，也就是總統。","s":""},{"w":"The meeting is next Friday, that is, the 20th.","p":"conj.","d":"that is · example","c":"會議在下週五，也就是二十號。","s":""},{"w":"He is a polyglot, that is, someone who speaks many languages.","p":"conj.","d":"that is · example","c":"他是個多語者，也就是會說多種語言的人。","s":""},{"w":"He didn't pass the exam; in other words, he must take it again.","p":"conj.","d":"in other words · example","c":"他沒通過考試；換句話說，他必須重考。","s":""},{"w":"The company is cutting costs. In other words, some of us will lose our jobs.","p":"conj.","d":"in other words · example","c":"公司在削減成本。換句話說，我們有些人會失業。","s":""},{"w":"To illustrate, consider what happens when interest rates rise.","p":"conj.","d":"to illustrate · example","c":"舉例來說，想想利率上升時會發生什麼。","s":""},{"w":"The rules are as follows: no food, no phones, no talking.","p":"conj.","d":"as follows · example","c":"規則如下：不准吃東西、不准用手機、不准說話。","s":""},{"w":"The report focuses on pollution, specifically plastic waste in the ocean.","p":"conj.","d":"specifically · example","c":"這份報告聚焦污染，特別是海洋中的塑膠垃圾。","s":""},{"w":"Everyone, including the teacher, laughed at the joke.","p":"conj.","d":"including · example","c":"每個人，包括老師，都被那個笑話逗笑了。","s":""},{"w":"The price covers everything, including meals and transportation.","p":"conj.","d":"including · example","c":"這個價格包含一切，包括餐食和交通。","s":""},{"w":"Leafy vegetables, like spinach, are rich in iron.","p":"conj.","d":"like · example","c":"葉菜類，像菠菜，富含鐵質。","s":""},{"w":"First of all, I would like to thank everyone for coming.","p":"conj.","d":"first of all · sequence","c":"首先，我想感謝大家的到來。","s":""},{"w":"First of all, read the question carefully before answering.","p":"conj.","d":"first of all · sequence","c":"首先，回答前要仔細讀題。","s":""},{"w":"To begin with, the hotel was far dirtier than the photos suggested.","p":"conj.","d":"to begin with · sequence","c":"首先，這家飯店比照片上髒得多。","s":""},{"w":"Initially, the plan seemed perfect, but problems soon appeared.","p":"conj.","d":"initially · sequence","c":"起初，計畫看似完美，但問題很快就出現了。","s":""},{"w":"At first I didn't like the city, but now I love it.","p":"conj.","d":"at first · sequence","c":"起初我不喜歡這座城市，但現在我愛上了它。","s":""},{"w":"Mix the flour and eggs; then add the milk slowly.","p":"conj.","d":"then · sequence","c":"把麵粉和蛋混合；然後慢慢加入牛奶。","s":""}]},{"unit":9,"theme":"next – at last","cards":[{"w":"Next, we will look at the causes of the problem.","p":"conj.","d":"next · sequence","c":"接下來，我們來看看這個問題的原因。","s":""},{"w":"We watched a movie and went for ice cream afterward.","p":"conj.","d":"afterward · sequence","c":"我們看了電影，之後去吃冰淇淋。","s":""},{"w":"Afterward, she regretted what she had said.","p":"conj.","d":"afterward · sequence","c":"事後，她後悔自己說過的話。","s":""},{"w":"He apologized afterwards, but the damage had been done.","p":"conj.","d":"afterwards · sequence","c":"他事後道了歉，但傷害已經造成。","s":""},{"w":"He was arrested and subsequently charged with theft.","p":"conj.","d":"subsequently · sequence","c":"他被逮捕，隨後被控竊盜。","s":""},{"w":"The company was sold and subsequently renamed.","p":"conj.","d":"subsequently · sequence","c":"這家公司被出售，隨後更名。","s":""},{"w":"She moved to Canada in 2010 and lived there thereafter.","p":"conj.","d":"thereafter · sequence","c":"她在2010年搬到加拿大，此後一直住在那裡。","s":""},{"w":"Boil the pasta; meanwhile, prepare the sauce.","p":"conj.","d":"meanwhile · sequence","c":"煮義大利麵；同時，準備醬料。","s":""},{"w":"The president met with leaders abroad. Meanwhile, protests grew at home.","p":"conj.","d":"meanwhile · sequence","c":"總統在國外會見領袖。與此同時，國內抗議擴大。","s":""},{"w":"The doctor will see you soon. In the meantime, please fill out this form.","p":"conj.","d":"in the meantime · sequence","c":"醫生很快就會看診。在此期間，請填寫這張表格。","s":""},{"w":"The new school opens next year; in the meantime, students use temporary classrooms.","p":"conj.","d":"in the meantime · sequence","c":"新學校明年開幕；在此期間，學生使用臨時教室。","s":""},{"w":"The repairs will take a week; in the meantime, use the back door.","p":"conj.","d":"meantime · sequence","c":"維修要一週；在此期間，請走後門。","s":""},{"w":"The two events were broadcast simultaneously on different channels.","p":"conj.","d":"simultaneously · sequence","c":"這兩個活動在不同頻道同時播出。","s":""},{"w":"He wants to save money, but at the same time he loves shopping.","p":"conj.","d":"at the same time · sequence","c":"他想存錢，但同時他又愛購物。","s":""},{"w":"At the same time, we must not ignore the risks.","p":"conj.","d":"at the same time · sequence","c":"同時，我們也不能忽視風險。","s":""},{"w":"She now works in Taipei; previously, she taught in Tainan.","p":"conj.","d":"previously · sequence","c":"她現在在台北工作；先前，她在台南教書。","s":""},{"w":"The building, formerly a bank, is now a museum.","p":"conj.","d":"formerly · sequence","c":"這座建築先前是銀行，現在是博物館。","s":""},{"w":"Prior to the meeting, please read the attached report.","p":"conj.","d":"prior to · sequence","c":"會議之前，請閱讀附上的報告。","s":""},{"w":"Passengers must check in prior to departure.","p":"conj.","d":"prior to · sequence","c":"乘客必須在出發前辦理登機。","s":""},{"w":"If you plan to visit, please let us know beforehand.","p":"conj.","d":"beforehand · sequence","c":"如果你打算來訪，請事先告知我們。","s":""},{"w":"After months of searching, he eventually found a job.","p":"conj.","d":"eventually · sequence","c":"找了好幾個月後，他終於找到工作。","s":""},{"w":"Ultimately, the decision rests with the school principal.","p":"conj.","d":"ultimately · sequence","c":"最終，決定權在校長手上。","s":""},{"w":"The company ultimately failed because it ignored its customers.","p":"conj.","d":"ultimately · sequence","c":"這家公司最終失敗，因為它忽視了顧客。","s":""},{"w":"Finally, I would like to thank my parents for their support.","p":"conj.","d":"finally · sequence","c":"最後，我想感謝父母的支持。","s":""},{"w":"Lastly, remember to turn off the lights when you leave.","p":"conj.","d":"lastly · sequence","c":"最後，離開時記得關燈。","s":""},{"w":"Last but not least, I want to thank our volunteers.","p":"conj.","d":"last but not least · sequence","c":"最後但同樣重要的是，我要感謝我們的志工。","s":""},{"w":"In the end, they decided to cancel the trip.","p":"conj.","d":"in the end · sequence","c":"最後，他們決定取消旅行。","s":""},{"w":"After hours of waiting, the train arrived at last.","p":"conj.","d":"at last · sequence","c":"等了好幾個小時，火車終於來了。","s":""}]},{"unit":10,"theme":"once – what if","cards":[{"w":"Once you have finished, please hand in your paper.","p":"conj.","d":"once · sequence","c":"一旦你完成了，請交卷。","s":""},{"w":"Once a popular singer, he now lives quietly in the countryside.","p":"conj.","d":"once · sequence","c":"他曾是當紅歌手，如今在鄉間過著平靜生活。","s":""},{"w":"Call me as soon as you arrive at the station.","p":"conj.","d":"as soon as · sequence","c":"你一到車站就打給我。","s":""},{"w":"No sooner had she sat down than the phone rang.","p":"conj.","d":"no sooner … than · sequence","c":"她剛坐下，電話就響了。","s":""},{"w":"Not until he left did I realize how much I needed him.","p":"conj.","d":"until · sequence","c":"直到他離開，我才明白我多需要他。","s":""},{"w":"Wait here until I come back.","p":"conj.","d":"until · sequence","c":"在這裡等到我回來。","s":""},{"w":"Whenever I feel stressed, I go for a long walk.","p":"conj.","d":"whenever · sequence","c":"每當我感到壓力，我就去散步。","s":""},{"w":"By the time we arrived, the concert had already begun.","p":"conj.","d":"by the time · sequence","c":"我們到達時，演唱會已經開始了。","s":""},{"w":"Why did you buy the car in the first place?","p":"conj.","d":"in the first place · sequence","c":"你當初為什麼買這輛車？","s":""},{"w":"I never wanted to come here in the first place.","p":"conj.","d":"in the first place · sequence","c":"我一開始就不想來這裡。","s":""},{"w":"If it rains tomorrow, the picnic will be moved indoors.","p":"conj.","d":"if · condition","c":"如果明天下雨，野餐將改到室內。","s":""},{"w":"If only I had listened to your advice!","p":"conj.","d":"if · condition","c":"要是我當初聽了你的建議就好了！","s":""},{"w":"You will miss the bus unless you leave right now.","p":"conj.","d":"unless · condition","c":"除非你現在就出發，否則會錯過公車。","s":""},{"w":"Unless it rains, the match will start at three.","p":"conj.","d":"unless · condition","c":"除非下雨，否則比賽三點開始。","s":""},{"w":"You can borrow my car provided that you return it by Sunday.","p":"conj.","d":"provided that · condition","c":"只要你週日前還車，就可以借我的車。","s":""},{"w":"Provided that everyone agrees, we will start next week.","p":"conj.","d":"provided that · condition","c":"只要大家同意，我們下週就開始。","s":""},{"w":"I will lend you the money, providing that you pay me back soon.","p":"conj.","d":"providing that · condition","c":"只要你很快還我，我就借錢給你。","s":""},{"w":"You can stay here as long as you keep the place clean.","p":"conj.","d":"as long as · condition","c":"只要你保持環境整潔，就可以住在這裡。","s":""},{"w":"As long as you try your best, the result doesn't matter.","p":"conj.","d":"as long as · condition","c":"只要你盡力，結果並不重要。","s":""},{"w":"So long as the weather holds, we will camp by the lake.","p":"conj.","d":"so long as · condition","c":"只要天氣維持良好，我們就在湖邊露營。","s":""},{"w":"He agreed to help on condition that his name was kept secret.","p":"conj.","d":"on condition that · condition","c":"他同意幫忙，條件是不公開他的名字。","s":""},{"w":"Take an umbrella in case it rains later.","p":"conj.","d":"in case · condition","c":"帶把傘，以防稍後下雨。","s":""},{"w":"In case of fire, use the stairs, not the elevator.","p":"conj.","d":"in case · condition","c":"如遇火災，請走樓梯，不要搭電梯。","s":""},{"w":"In the event of an earthquake, stay away from windows.","p":"conj.","d":"in the event of · condition","c":"如果發生地震，要遠離窗戶。","s":""},{"w":"Suppose you won the lottery; what would you do first?","p":"conj.","d":"suppose · condition","c":"假設你中了樂透；你會先做什麼？","s":""},{"w":"Supposing it snows, will the school still be open?","p":"conj.","d":"supposing · condition","c":"假設下雪，學校還會開放嗎？","s":""},{"w":"Assuming that the train is on time, we will arrive by noon.","p":"conj.","d":"assuming that · condition","c":"假設火車準時，我們中午前會到。","s":""},{"w":"What if the plane is delayed and we miss the connection?","p":"conj.","d":"what if · condition","c":"如果飛機延誤、我們錯過轉機怎麼辦？","s":""}]},{"unit":11,"theme":"otherwise – in general","cards":[{"w":"Hurry up; otherwise, we will miss the beginning of the movie.","p":"conj.","d":"otherwise · condition","c":"快點；否則我們會錯過電影開頭。","s":""},{"w":"Wear a coat; otherwise, you will catch a cold.","p":"conj.","d":"otherwise · condition","c":"穿上外套；否則你會感冒。","s":""},{"w":"The food was a bit salty, but otherwise the meal was perfect.","p":"conj.","d":"otherwise · condition","c":"食物有點鹹，但除此之外這一餐很完美。","s":""},{"w":"Finish your homework now, or else you can't watch TV.","p":"conj.","d":"or else · condition","c":"現在做完功課，否則不能看電視。","s":""},{"w":"Even if you offered me a million dollars, I wouldn't sell it.","p":"conj.","d":"even if · condition","c":"即使你出一百萬，我也不賣。","s":""},{"w":"I will go to the concert even if it rains.","p":"conj.","d":"even if · condition","c":"即使下雨，我也會去聽演唱會。","s":""},{"w":"You will succeed only if you are willing to work hard.","p":"conj.","d":"only if · condition","c":"只有願意努力，你才會成功。","s":""},{"w":"Only if we act now can we save the forest.","p":"conj.","d":"only if · condition","c":"只有現在行動，我們才能救這片森林。","s":""},{"w":"Are you free this weekend? If so, let's go hiking.","p":"conj.","d":"if so · condition","c":"你這週末有空嗎？如果有，我們去爬山吧。","s":""},{"w":"Check whether the file is saved; if not, save it now.","p":"conj.","d":"if not · condition","c":"檢查檔案是否已儲存；如果沒有，現在就存。","s":""},{"w":"The situation hasn't improved; if anything, it has gotten worse.","p":"conj.","d":"if anything · condition","c":"情況沒有好轉；如果真要說，反而更糟了。","s":""},{"w":"He isn't shy; if anything, he talks too much.","p":"conj.","d":"if anything · condition","c":"他並不害羞；要說的話，他反而話太多。","s":""},{"w":"We will work overtime if necessary to meet the deadline.","p":"conj.","d":"if necessary · condition","c":"如有必要，我們會加班以趕上期限。","s":""},{"w":"Please reply by Friday, if possible.","p":"conj.","d":"if possible · condition","c":"如果可能，請在週五前回覆。","s":""},{"w":"In sum, the project was costly but ultimately successful.","p":"conj.","d":"in sum · summary","c":"總之，這個專案花費高昂，但最終成功。","s":""},{"w":"In summary, exercise benefits both the body and the mind.","p":"conj.","d":"in summary · summary","c":"總而言之，運動對身心都有益。","s":""},{"w":"To sum up, we need more time and more money.","p":"conj.","d":"to sum up · summary","c":"總結來說，我們需要更多時間和金錢。","s":""},{"w":"In conclusion, I believe the new policy will benefit everyone.","p":"conj.","d":"in conclusion · summary","c":"總之，我相信新政策會讓每個人受益。","s":""},{"w":"To conclude, let me thank everyone who made this possible.","p":"conj.","d":"to conclude · summary","c":"最後，讓我感謝所有促成此事的人。","s":""},{"w":"In short, the plan failed because nobody supported it.","p":"conj.","d":"in short · summary","c":"簡而言之，計畫失敗是因為沒人支持。","s":""},{"w":"In brief, the company needs to cut costs quickly.","p":"conj.","d":"in brief · summary","c":"簡單地說，公司需要迅速削減成本。","s":""},{"w":"In a word, the trip was unforgettable.","p":"conj.","d":"in a word · summary","c":"一句話，這趟旅行令人難忘。","s":""},{"w":"Briefly, the new law bans smoking in all public parks.","p":"conj.","d":"briefly · summary","c":"簡單來說，新法禁止在所有公園吸菸。","s":""},{"w":"Overall, the students' performance has improved this year.","p":"conj.","d":"overall · summary","c":"整體而言，學生今年的表現有所進步。","s":""},{"w":"The service was slow, but overall the hotel was pleasant.","p":"conj.","d":"overall · summary","c":"服務很慢，但整體來說這家飯店令人愉快。","s":""},{"w":"On the whole, I think the new system works well.","p":"conj.","d":"on the whole · summary","c":"大體上，我認為新制度運作良好。","s":""},{"w":"All in all, it was a successful and enjoyable trip.","p":"conj.","d":"all in all · summary","c":"總的來說，這是一次成功又愉快的旅行。","s":""},{"w":"In general, children learn languages faster than adults.","p":"conj.","d":"in general · summary","c":"一般來說，兒童學語言比成人快。","s":""}]},{"unit":12,"theme":"generally speaking – on the one hand","cards":[{"w":"Generally speaking, the climate here is mild all year round.","p":"conj.","d":"generally speaking · summary","c":"一般而言，這裡的氣候全年溫和。","s":""},{"w":"By and large, the reviews of the film were positive.","p":"conj.","d":"by and large · summary","c":"大體上，這部電影的評價是正面的。","s":""},{"w":"For the most part, the students behaved well on the trip.","p":"conj.","d":"for the most part · summary","c":"大部分時候，學生們在旅途中表現良好。","s":""},{"w":"The success of the project was largely due to teamwork.","p":"conj.","d":"largely · summary","c":"這個專案的成功主要歸功於團隊合作。","s":""},{"w":"The old theory has been largely abandoned.","p":"conj.","d":"largely · summary","c":"舊理論大致上已被捨棄。","s":""},{"w":"The audience was mostly young people in their twenties.","p":"conj.","d":"mostly · summary","c":"觀眾大多是二十幾歲的年輕人。","s":""},{"w":"The course is mainly intended for beginners.","p":"conj.","d":"mainly · summary","c":"這門課主要是為初學者設計的。","s":""},{"w":"The accident was partly caused by the slippery road.","p":"conj.","d":"partly · summary","c":"這起事故部分是由於路面滑所造成。","s":""},{"w":"I agree with you, but only partly.","p":"conj.","d":"partly · summary","c":"我同意你，但只是部分同意。","s":""},{"w":"Roughly speaking, half of the students passed the test.","p":"conj.","d":"roughly · summary","c":"粗略地說，有一半的學生通過考試。","s":""},{"w":"The two cities are roughly the same size.","p":"conj.","d":"roughly · summary","c":"這兩座城市大小大致相同。","s":""},{"w":"The first chapter was boring; likewise, the second put me to sleep.","p":"conj.","d":"likewise · comparison","c":"第一章很無聊；同樣地，第二章讓我睡著了。","s":""},{"w":"He donated generously, and his wife did likewise.","p":"conj.","d":"likewise · comparison","c":"他慷慨捐款，他太太也照做。","s":""},{"w":"Water the plants weekly; likewise, feed them once a month.","p":"conj.","d":"likewise · comparison","c":"每週澆水；同樣地，每月施肥一次。","s":""},{"w":"Cats need regular care; similarly, dogs require daily attention.","p":"conj.","d":"similarly · comparison","c":"貓需要定期照顧；同樣地，狗需要每天關注。","s":""},{"w":"Children copy their parents. In the same way, students imitate their teachers.","p":"conj.","d":"in the same way · comparison","c":"孩子模仿父母。同樣地，學生模仿老師。","s":""},{"w":"Diet is important; equally, regular exercise matters.","p":"conj.","d":"equally · comparison","c":"飲食很重要；同樣重要的是規律運動。","s":""},{"w":"Costs have risen, and prices have gone up correspondingly.","p":"conj.","d":"correspondingly · comparison","c":"成本上升，價格也隨之相應上漲。","s":""},{"w":"Last winter was mild. By comparison, this one has been bitterly cold.","p":"conj.","d":"by comparison · comparison","c":"去年冬天溫和。相較之下，今年冷得刺骨。","s":""},{"w":"In comparison with last year, sales have grown by ten percent.","p":"conj.","d":"in comparison with · comparison","c":"與去年相比，銷售成長了百分之十。","s":""},{"w":"He prefers tea as opposed to coffee in the morning.","p":"conj.","d":"as opposed to · comparison","c":"早上他偏好喝茶而非咖啡。","s":""},{"w":"Unlike her sister, Amy is outgoing and loves parties.","p":"conj.","d":"unlike · comparison","c":"和她姐姐不同，艾咪外向又愛派對。","s":""},{"w":"The debate was about quality versus quantity.","p":"conj.","d":"versus · comparison","c":"這場辯論是關於品質與數量之爭。","s":""},{"w":"Tonight's game is Taiwan versus Japan.","p":"conj.","d":"versus · comparison","c":"今晚的比賽是台灣對日本。","s":""},{"w":"You can pay by card; alternatively, you can pay in cash.","p":"conj.","d":"alternatively · alternative","c":"你可以刷卡；或者，你也可以付現。","s":""},{"w":"He is a teacher, or rather, a professor at the university.","p":"conj.","d":"or rather · alternative","c":"他是老師，更準確地說，是大學教授。","s":""},{"w":"He doesn't eat meat, nor does he drink milk.","p":"conj.","d":"nor · alternative","c":"他不吃肉，也不喝牛奶。","s":""},{"w":"On the one hand, the city is exciting; on the other, it is exhausting.","p":"conj.","d":"on the one hand · contrast","c":"一方面，這座城市令人興奮；另一方面，它令人疲憊。","s":""}]},{"unit":13,"theme":"whereby – apparently","cards":[{"w":"The school has a system whereby students can earn extra credit.","p":"conj.","d":"whereby · clarification","c":"學校有一套制度，讓學生能藉此獲得額外學分。","s":""},{"w":"They signed an agreement whereby both sides share the costs.","p":"conj.","d":"whereby · clarification","c":"他們簽了一份協議，據此雙方分攤費用。","s":""},{"w":"He wrote a report wherein he explained the causes of the failure.","p":"conj.","d":"wherein · clarification","c":"他寫了一份報告，在其中解釋了失敗的原因。","s":""},{"w":"She announced her resignation, whereupon the room fell silent.","p":"conj.","d":"whereupon · sequence","c":"她宣布辭職，隨即全場陷入沉默。","s":""},{"w":"I hereby declare the meeting open.","p":"conj.","d":"hereby · clarification","c":"我在此宣布會議開始。","s":""},{"w":"With regard to your question, I will answer it in writing.","p":"conj.","d":"with regard to · clarification","c":"關於你的問題，我會以書面回覆。","s":""},{"w":"Please contact us regarding any problems with your order.","p":"conj.","d":"regarding · clarification","c":"關於訂單的任何問題，請與我們聯繫。","s":""},{"w":"He said nothing regarding his future plans.","p":"conj.","d":"regarding · clarification","c":"關於未來的計畫，他什麼也沒說。","s":""},{"w":"There are many rumors concerning the actor's private life.","p":"conj.","d":"concerning · clarification","c":"有許多關於這位演員私生活的傳聞。","s":""},{"w":"Concerning your request, we need a few more days to decide.","p":"conj.","d":"concerning · clarification","c":"關於你的請求，我們需要再幾天決定。","s":""},{"w":"The food was excellent. As for the service, it was slow.","p":"conj.","d":"as for · clarification","c":"食物很棒。至於服務，就慢了。","s":""},{"w":"There is some doubt as to whether the plan will work.","p":"conj.","d":"as to · clarification","c":"這個計畫是否可行仍有疑慮。","s":""},{"w":"In terms of price, this phone is the best choice.","p":"conj.","d":"in terms of · clarification","c":"就價格而言，這款手機是最佳選擇。","s":""},{"w":"As far as I am concerned, the matter is closed.","p":"conj.","d":"as far as … is concerned · clarification","c":"就我而言，這件事已經結束了。","s":""},{"w":"As far as cost is concerned, the plan is unrealistic.","p":"conj.","d":"as far as … is concerned · clarification","c":"就成本而言，這個計畫不切實際。","s":""},{"w":"When it comes to cooking, my father is the expert.","p":"conj.","d":"when it comes to · clarification","c":"說到做菜，我爸爸才是專家。","s":""},{"w":"Apart from a few spelling mistakes, the essay is excellent.","p":"conj.","d":"apart from · addition","c":"除了幾個拼字錯誤，這篇文章很棒。","s":""},{"w":"Apart from English, what other languages do you speak?","p":"conj.","d":"apart from · addition","c":"除了英語，你還會說什麼語言？","s":""},{"w":"Aside from the price, I have no complaints about the car.","p":"conj.","d":"aside from · addition","c":"除了價格，我對這輛車沒什麼抱怨。","s":""},{"w":"Everyone passed the test except for two students.","p":"conj.","d":"except for · contrast","c":"除了兩位學生，大家都通過了考試。","s":""},{"w":"I know nothing about him other than his name.","p":"conj.","d":"other than · contrast","c":"除了名字，我對他一無所知。","s":""},{"w":"Dinner is not ready; in the meantime, help yourself to some snacks.","p":"conj.","d":"in the meantime · addition","c":"晚餐還沒好；在此期間，請自己拿點心吃。","s":""},{"w":"Presumably, the meeting has been canceled, since nobody is here.","p":"conj.","d":"presumably · clarification","c":"大概是會議取消了，因為沒人在這裡。","s":""},{"w":"He left early, presumably to catch his train.","p":"conj.","d":"presumably · clarification","c":"他提早離開，大概是去趕火車。","s":""},{"w":"The castle is supposedly haunted, but I don't believe it.","p":"conj.","d":"supposedly · clarification","c":"據說這座城堡有鬼，但我不信。","s":""},{"w":"The new medicine is supposedly very effective.","p":"conj.","d":"supposedly · clarification","c":"據說這種新藥非常有效。","s":""},{"w":"Apparently, the store closes early on Sundays.","p":"conj.","d":"apparently · clarification","c":"顯然，這家店週日提早關門。","s":""},{"w":"She has apparently decided to quit her job.","p":"conj.","d":"apparently · clarification","c":"她顯然已決定辭職。","s":""}]},{"unit":14,"theme":"seemingly – lately","cards":[{"w":"The seemingly simple question puzzled everyone.","p":"conj.","d":"seemingly · clarification","c":"這個看似簡單的問題難倒了所有人。","s":""},{"w":"She is arguably the best player of her generation.","p":"conj.","d":"arguably · clarification","c":"她可以說是她那一代最棒的球員。","s":""},{"w":"Somehow, the cat managed to open the door by itself.","p":"conj.","d":"somehow · clarification","c":"不知怎地，那隻貓竟然自己把門打開了。","s":""},{"w":"We will finish the job somehow.","p":"conj.","d":"somehow · clarification","c":"我們總會想辦法完成這份工作。","s":""},{"w":"He had barely left the house when it started to rain.","p":"conj.","d":"barely · emphasis","c":"他剛離開家就開始下雨了。","s":""},{"w":"There was barely enough food for everyone.","p":"conj.","d":"barely · emphasis","c":"食物幾乎不夠所有人吃。","s":""},{"w":"Scarcely had she opened the book when the lights went out.","p":"conj.","d":"scarcely · emphasis","c":"她剛打開書，燈就熄了。","s":""},{"w":"I could scarcely believe my eyes.","p":"conj.","d":"scarcely · emphasis","c":"我幾乎不敢相信自己的眼睛。","s":""},{"w":"Hardly anyone came to the meeting because of the storm.","p":"conj.","d":"hardly · emphasis","c":"由於暴風雨，幾乎沒人來開會。","s":""},{"w":"It is hardly surprising that he failed; he never studied.","p":"conj.","d":"hardly · emphasis","c":"他不及格並不令人意外；他從不讀書。","s":""},{"w":"No doubt you have heard the news already.","p":"conj.","d":"no doubt · emphasis","c":"你無疑已經聽到消息了。","s":""},{"w":"She is, without doubt, the hardest-working person I know.","p":"conj.","d":"without doubt · emphasis","c":"她無疑是我認識最努力的人。","s":""},{"w":"By all means, bring your friends to the party.","p":"conj.","d":"by all means · emphasis","c":"當然可以，帶你的朋友來派對吧。","s":""},{"w":"The problem is by no means solved.","p":"conj.","d":"by no means · emphasis","c":"這個問題絕對還沒解決。","s":""},{"w":"By no means should you open that door.","p":"conj.","d":"by no means · emphasis","c":"你絕對不可以打開那扇門。","s":""},{"w":"The delay was in no way our fault.","p":"conj.","d":"in no way · emphasis","c":"這次延誤絕非我們的錯。","s":""},{"w":"On no account should the password be shared.","p":"conj.","d":"on no account · emphasis","c":"絕不可分享密碼。","s":""},{"w":"Under no circumstances will refunds be given.","p":"conj.","d":"under no circumstances · emphasis","c":"無論在任何情況下都不退款。","s":""},{"w":"Nowhere is the problem more serious than in big cities.","p":"conj.","d":"nowhere · emphasis","c":"這個問題在大城市最為嚴重。","s":""},{"w":"The missing keys were nowhere to be found.","p":"conj.","d":"nowhere · emphasis","c":"遺失的鑰匙到處都找不到。","s":""},{"w":"The product is cheaper here than elsewhere in the city.","p":"conj.","d":"elsewhere · contrast","c":"這個產品在這裡比城裡其他地方便宜。","s":""},{"w":"If the hotel is full, we will have to look elsewhere.","p":"conj.","d":"elsewhere · contrast","c":"如果飯店滿了，我們得去別處找。","s":""},{"w":"Nowadays, most people shop online rather than in stores.","p":"conj.","d":"nowadays · clarification","c":"如今，大多數人在網路上購物而非在店裡。","s":""},{"w":"Nothing lasts forever, not even the hardest rock.","p":"conj.","d":"forever · emphasis","c":"沒有什麼是永恆的，即使是最硬的岩石。","s":""},{"w":"He is forever complaining about the weather.","p":"conj.","d":"forever · emphasis","c":"他老是在抱怨天氣。","s":""},{"w":"The manager will be with you shortly.","p":"conj.","d":"shortly · sequence","c":"經理很快就會來見你。","s":""},{"w":"Shortly after midnight, the power went out.","p":"conj.","d":"shortly · sequence","c":"午夜過後不久，就停電了。","s":""},{"w":"Have you seen any good movies lately?","p":"conj.","d":"lately · sequence","c":"你最近有看什麼好電影嗎？","s":""}]},{"unit":15,"theme":"sometime – beneath","cards":[{"w":"Let's have lunch together sometime next week.","p":"conj.","d":"sometime · sequence","c":"我們下週找個時間一起吃午餐吧。","s":""},{"w":"Someday, I hope to travel around the world.","p":"conj.","d":"someday · sequence","c":"總有一天，我希望能環遊世界。","s":""},{"w":"We flew to London via Hong Kong.","p":"conj.","d":"via · clarification","c":"我們經由香港飛往倫敦。","s":""},{"w":"Send me the file via email, please.","p":"conj.","d":"via · clarification","c":"請透過電子郵件把檔案寄給我。","s":""},{"w":"Students work alongside professionals during the internship.","p":"conj.","d":"alongside · addition","c":"實習期間，學生與專業人士並肩工作。","s":""},{"w":"The new drug is used alongside traditional treatments.","p":"conj.","d":"alongside · addition","c":"這種新藥與傳統療法一併使用。","s":""},{"w":"In the midst of the crisis, the mayor remained calm.","p":"conj.","d":"in the midst of · sequence","c":"在危機之中，市長保持冷靜。","s":""},{"w":"The company closed amid growing financial problems.","p":"conj.","d":"amid · sequence","c":"這家公司在日益嚴重的財務問題中倒閉。","s":""},{"w":"Beneath his calm appearance, he was extremely nervous.","p":"conj.","d":"beneath · clarification","c":"在他冷靜的外表下，他其實極度緊張。","s":""},{"w":"She felt the job was beneath her.","p":"conj.","d":"beneath · clarification","c":"她覺得這份工作配不上她。","s":""}]}];
